{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "The bill also adds child trafficking prevention and awareness education to a list in section 49-1-1002(a).",
      "rationale": "Identifies the amended provision and the added subject. The exact placement within the list is not material to the addition's legal meaning."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "It deletes subdivision (a)(13)(B) of section 49-6-1304",
      "rationale": "Identifies the exact subdivision deleted."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "It deletes subdivision (a)(13)(B) of section 49-6-1304 and the second sentence of subsection (d) of that section.",
      "rationale": "Identifies the second sentence of the specified subsection as deleted."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "The bill defines child trafficking as a human trafficking offense, as defined in section 39-13-314, in which the victim is under 18.",
      "rationale": "Conveys the referenced offense definition and the victim's age threshold."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "This bill would require all Tennessee public schools, including public charter schools, to teach child trafficking prevention and awareness as part of health education in every grade from kindergarten through twelfth grade.",
      "rationale": "Covers the mandatory instruction, all public schools, its placement in health education, and every K–12 grade."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "School systems (LEAs) and charter schools would have to use the state board of education's health education standards. The instruction must fit each student's age and grade and must build each year through developmentally appropriate teaching and skill building.",
      "rationale": "Conveys the responsible schools, governing standards, age and grade appropriateness, and annual developmental progression."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "A school system or charter school may use a qualified healthcare professional or social worker to help teach, but only if that person meets the requirements for assisting in teaching family life under section 49-6-1303.",
      "rationale": "Covers the optional assistance, eligible professionals, and required family-life teaching qualifications."
    },
    {
      "proposition_id": "P8",
      "status": "full",
      "summary_quote": "By August 1, 2026, and every August 1 after that, each local board of education and charter school governing body must send the commissioner of education an implementation plan and post it on its website. The plan must describe how instruction will be delivered at each grade level, the professional qualifications of the person teaching, and the materials and resources used.",
      "rationale": "Conveys the initial and recurring deadlines, responsible bodies, recipient, website publication, and all required plan contents."
    },
    {
      "proposition_id": "P9",
      "status": "full",
      "summary_quote": "By July 1, 2027, and every July 1 after that, each must also send the commissioner a report. The report must confirm that the required instruction was given in the previous school year and repeat the plan information.",
      "rationale": "Conveys both deadlines, the recipient, prior-year verification, and required plan information. The preceding plan description supplies the responsible bodies and information incorporated into the report."
    },
    {
      "proposition_id": "P10",
      "status": "full",
      "summary_quote": "The bill would take effect when it becomes law and would apply to the 2026-2027 school year and later years.",
      "rationale": "Conveys both the effective-date trigger and the school years to which the act applies."
    }
  ]
}
